/**
 * Creates a debounced function that delays invoking `func` until after `wait`
 * milliseconds have elapsed since the last time the debounced function was invoked.
 *
 * @template {(...args: any[]) => any} T
 * @param {T} func - The function to debounce.
 * @param {number} wait - The number of milliseconds to delay.
 * @param {boolean} [immediate=false] - If true, invoke `func` on the leading edge
 *   of the timeout instead of the trailing edge.
 * @returns {(...args: Parameters<T>) => void} A new debounced function.
 *
 * @example
 * // Basic usage — logs after user stops typing for 300ms
 * const debouncedSearch = debounce((query) => {
 *   console.log('Searching for:', query);
 * }, 300);
 *
 * window.addEventListener('input', (e) => debouncedSearch(e.target.value));
 *
 * @example
 * // With `immediate` flag — fires on the first call, then waits
 * const saveDraft = debounce(() => {
 *   console.log('Draft saved!');
 * }, 1000, true);
 */
function debounce(func, wait, immediate = false) {
  let timeoutId = null;

  /**
   * The debounced wrapper function.
   *
   * @param {...any} args - Arguments passed to the original function.
   * @returns {void}
   */
  return function debounced(...args) {
    const context = this;

    const later = () => {
      timeoutId = null;
      if (!immediate) {
        func.apply(context, args);
      }
    };

    const callNow = immediate && timeoutId === null;

    clearTimeout(timeoutId);
    timeoutId = setTimeout(later, wait);

    if (callNow) {
      func.apply(context, args);
    }
  };
}
```

### Usage Example

```javascript
// ── Example 1: Search input ──────────────────────────────────────
const searchInput = document.getElementById('search');

const fetchResults = debounce((query) => {
  console.log(`Fetching results for: "${query}"`);
  // fetch(`/api/search?q=${query}`) ...
}, 300);

searchInput.addEventListener('input', (e) => {
  fetchResults(e.target.value);
});

// ── Example 2: Window resize ────────────────────────────────────
const handleResize = debounce(() => {
  console.log('Window resized:', window.innerWidth, 'x', window.innerHeight);
}, 250);

window.addEventListener('resize', handleResize);

// ── Example 3: Leading-edge (immediate) execution ───────────────
const onFirstClick = debounce(() => {
  console.log('Button clicked — fires immediately, then ignores rapid clicks.');
}, 1000, true);

document.getElementById('myBtn').addEventListener('click', onFirstClick);
```

### How It Works

| Call | What Happens |
|---|---|
| **1st call** | Timer starts. If `immediate=true`, `func` fires right away. |
| **Subsequent calls** (within `wait`) | Previous timer is **cleared** and a new one begins. |
| **No call for `wait` ms** | Timer fires → `func` executes (trailing edge). |

This pattern is ideal for **performance-sensitive** events like `input`, `scroll`, `resize`, and `mousemove`, where firing on every event would be wasteful.
